import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();

async function routeAndAnswer(question) {
  // Haiku classifies complexity — costs ~$0.000001 per call
  const classification = await client.messages.create({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 5,
    system: "Reply 'simple' or 'complex'. Simple = factual, single-step. Complex = analysis, judgment, or multi-step reasoning.",
    messages: [{ role: 'user', content: question }]
  });

  const complexity = classification.content[0].text.trim().toLowerCase();
  const model = complexity.includes('simple')
    ? 'claude-haiku-4-5-20251001'
    : 'claude-sonnet-4-6';

  const response = await client.messages.create({
    model,
    max_tokens: 300,
    messages: [{ role: 'user', content: question }]
  });

  console.log(`  → routed to: ${model}`);
  return response.content[0].text;
}

const testQuestions = [
  'What does HTTP stand for?',
  'Analyse the security tradeoffs between JWT and session-based auth for a 10M-user fintech app',
  'What year was Python created?',
  'Design a database schema for multi-tenant SaaS with usage-based billing',
];

for (const q of testQuestions) {
  console.log(`\nQ: ${q.slice(0, 70)}`);
  const answer = await routeAndAnswer(q);
  console.log(`A: ${answer.slice(0, 100)}...`);
}

import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();

// Simulate a large company knowledge base (repeated 6x to exceed 1,024 token minimum)
const COMPANY_DOCS = `
You are a customer support agent for TechCorp.

Product overview: TechCorp sells cloud data tools. Our three products are:
DataPipe (ETL automation), DataStore (managed PostgreSQL), and DataViz (dashboards).
Pricing: DataPipe $99/mo, DataStore $149/mo, DataViz $49/mo. Bundle: $249/mo.
Support SLA: free tier 48h response, paid tier 4h response, enterprise 1h response.
Refund policy: 30-day money-back guarantee, no questions asked.
`.repeat(6);  // repeat to exceed 1,024 token minimum for this demo

async function answerWithCache(question) {
  const response = await client.messages.create({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 150,
    system: [
      {
        type: 'text',
        text: COMPANY_DOCS,
        cache_control: { type: 'ephemeral' }  // mark this block for caching
      }
    ],
    messages: [{ role: 'user', content: question }]
  });

  const u = response.usage;
  const created = u.cache_creation_input_tokens || 0;
  const read    = u.cache_read_input_tokens || 0;
  const status  = created > 0 ? 'CACHE MISS (full price)' : 'CACHE HIT  (~10% price)';
  console.log(`  ${status} | created=${created} read=${read} regular=${u.input_tokens}`);
  return response.content[0].text;
}

console.log('=== Call 1 (writes the cache) ===');
await answerWithCache('What is your refund policy?');

console.log('\n=== Call 2 (reads from cache) ===');
await answerWithCache('How much does the bundle cost?');

console.log('\n=== Call 3 (reads from cache) ===');
await answerWithCache('What is the support SLA for paid tier?');

import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();

const emails = [
  "You've won $1,000,000! Click here now",
  "Your AWS invoice for $23.50 is ready",
  "URGENT: Your account will be suspended",
  "Team standup moved to 3pm tomorrow",
  "Exclusive offer — claim your free gift card",
];

const batch = await client.messages.batches.create({
  requests: emails.map((email, i) => ({
    custom_id: `email-${i}`,
    params: {
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 5,
      system: "Reply 'spam' or 'not_spam' only.",
      messages: [{ role: 'user', content: email }]
    }
  }))
});

console.log(`Batch submitted: ${batch.id}`);
console.log(`Status: ${batch.processing_status}`);
console.log('Poll status:  await client.messages.batches.retrieve(batchId)');
console.log('Get results:  await client.messages.batches.results(batchId)');
console.log('(results available when processing_status === "ended")');
